}
fn equal_fields<C:NativeSchemaControl>(a:&[PackSchemaField],b:&[PackSchemaField],control:&mut C)->Result<bool,ValueError>{
    if a.len()!=b.len(){return Ok(false)}for(a,b)in a.iter().zip(b){control.step()?;if a.id!=b.id||a.optional!=b.optional||a.flatten!=b.flatten||compare_text(&a.key,&b.key,control)?!=Ordering::Equal||!equal_shape(&a.shape,&b.shape,control)?{return Ok(false)}}Ok(true)
}
fn reserve_map<K:std::hash::Hash+Eq,V,C:NativeSchemaControl>(map:&mut HashMap<K,V>,control:&mut C)->Result<(),ValueError>{control.charge(size_of::<(K,V)>().checked_add(160).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"schema map slot overflow"))?)?;map.try_reserve(1).map_err(|_|ValueError::new(ValueRefusalKind::AllocationFailed,"schema map allocation"))}

pub(super) fn graph<C:NativeSchemaControl>(spec:&RecordSpec,control:&mut C)->Result<PackSchemaGraph,ValueError>{
    control.scoped_stage(|control|{control.begin_stage(0)?;let mut nodes:Vec<(Vec<PackSchemaField>,Vec<usize>)>=Vec::new();let mut pending:Vec<RecordSpec>=Vec::new();let mut seen=HashMap::new();let mut cursor=0;
