    fields.insert(
        16,
        FieldValue::Wire(WireValue {
            from: WireNode { id: "a".to_string(), kind: Some("Kind".to_string()), port: None },
            edge: Some((true, WireNode { id: "b".to_string(), kind: None, port: Some("out".to_string()) })),
            edge_label: WireEdgeLabel::default(),
