//! 🔑️ Structural pack-schema identity, run natively and on `wasm32-wasip2`: the canonical graph of
//! every fixture schema equals its language-neutral JSON, an independent encoder reproduces the
//! canonical bytes, third-party `blake3` reproduces the pinned hash, nested changes flip it,
//! recursion and duplicated spec functions collapse, and text-only presentation is ignored.
use semio_framework_dsl_record::{producer, FieldSpec, NativeSchemaControl, RecordLayout, RecordSpec, RecordSpecProducer, Shape};
use semio_framework_pack_record::{schema_hash, PackSchemaGraph};

fn inner_spec() -> RecordSpec {
    RecordSpec::new(None, RecordLayout::Inline, vec![FieldSpec::new(0, "x", Shape::Float)])
}

fn inner_changed_spec() -> RecordSpec {
    RecordSpec::new(None, RecordLayout::Inline, vec![FieldSpec::new(0, "x", Shape::Int)])
}

fn other_spec() -> RecordSpec {
    RecordSpec::new(None, RecordLayout::Inline, vec![FieldSpec::new(0, "mode", Shape::Enum(vec![("beta".into(), 1), ("alpha".into(), 0)]))])
}

fn hashed_nested_spec(inner: RecordSpecProducer) -> RecordSpec {
    RecordSpec::new(
        Some("nested"),
        RecordLayout::Lines,
        vec![FieldSpec::new(2, "maybe", Shape::Record(other_producer())).optional(), FieldSpec::new(0, "inner", Shape::Record(inner)), FieldSpec::new(1, "items", Shape::List(Box::new(Shape::Record(inner))))],
    )
}

fn node_spec() -> RecordSpec {
    RecordSpec::new(Some("node"), RecordLayout::Inline, vec![FieldSpec::new(0, "name", Shape::Text), FieldSpec::new(1, "children", Shape::List(Box::new(Shape::Record(node_producer())))), FieldSpec::new(2, "alias", Shape::Record(node_twin_producer())).optional()])
}

fn node_twin_spec() -> RecordSpec {
    RecordSpec::new(None, RecordLayout::Lines, vec![FieldSpec::new(2, "alias", Shape::Record(node_producer())).optional(), FieldSpec::new(1, "children", Shape::List(Box::new(Shape::Record(node_twin_producer())))), FieldSpec::new(0, "name", Shape::Text)])
}

fn step_spec() -> RecordSpec {
    RecordSpec::new(Some("move"), RecordLayout::Inline, vec![FieldSpec::new(0, "to", Shape::Coord(3))])
}

fn wait_spec() -> RecordSpec {
    RecordSpec::new(Some("wait"), RecordLayout::Inline, vec![FieldSpec::new(0, "ms", Shape::UInt)])
}

fn row_spec() -> RecordSpec {
    RecordSpec::new(None, RecordLayout::Inline, vec![FieldSpec::new(0, "x", Shape::Float), FieldSpec::new(1, "y", Shape::Float)])
}

fn scalar_spec_controlled<C: NativeSchemaControl, const N: usize>(keyword: Option<&str>, layout: RecordLayout, definitions: [(u16, &str, Shape); N], control: &mut C) -> Result<RecordSpec, semio_framework_value::ValueError> {
    control.scoped_stage(|control| {
        control.begin_stage(N)?;
        let mut fields = control.allocate_vec(N)?;
        for (id, key, shape) in definitions {
            fields.push(producer::field(id, key, shape, control)?);
            control.step()?;
        }
        producer::record(keyword, layout, fields, control)
    })
}

fn inner_controlled<C: NativeSchemaControl>(control: &mut C) -> Result<RecordSpec, semio_framework_value::ValueError> {
    scalar_spec_controlled(None, RecordLayout::Inline, [(0, "x", Shape::Float)], control)
}

fn inner_changed_controlled<C: NativeSchemaControl>(control: &mut C) -> Result<RecordSpec, semio_framework_value::ValueError> {
    scalar_spec_controlled(None, RecordLayout::Inline, [(0, "x", Shape::Int)], control)
}

fn other_controlled<C: NativeSchemaControl>(control: &mut C) -> Result<RecordSpec, semio_framework_value::ValueError> {
    control.scoped_stage(|control| {
        control.begin_stage(2)?;
        let mut tags = control.allocate_vec(2)?;
        for (tag, ordinal) in [("beta", 1), ("alpha", 0)] {
            tags.push((control.copy_text(tag)?, ordinal));
            control.step()?;
        }
        scalar_spec_controlled(None, RecordLayout::Inline, [(0, "mode", Shape::Enum(tags))], control)
    })
}

fn node_controlled<C: NativeSchemaControl>(control: &mut C) -> Result<RecordSpec, semio_framework_value::ValueError> {
    control.scoped_stage(|control| {
        control.begin_stage(3)?;
        let mut fields = control.allocate_vec(3)?;
        fields.push(producer::field(0, "name", Shape::Text, control)?);
        control.step()?;
        let children = Shape::List(producer::boxed(Shape::Record(node_producer()), control)?);
        fields.push(producer::field(1, "children", children, control)?);
        control.step()?;
        fields.push(producer::field(2, "alias", Shape::Record(node_twin_producer()), control)?.optional());
        control.step()?;
        producer::record(Some("node"), RecordLayout::Inline, fields, control)
    })
}

fn node_twin_controlled<C: NativeSchemaControl>(control: &mut C) -> Result<RecordSpec, semio_framework_value::ValueError> {
    control.scoped_stage(|control| {
        control.begin_stage(3)?;
        let mut fields = control.allocate_vec(3)?;
        fields.push(producer::field(2, "alias", Shape::Record(node_producer()), control)?.optional());
        control.step()?;
        let children = Shape::List(producer::boxed(Shape::Record(node_twin_producer()), control)?);
        fields.push(producer::field(1, "children", children, control)?);
        control.step()?;
        fields.push(producer::field(0, "name", Shape::Text, control)?);
        control.step()?;
        producer::record(None, RecordLayout::Lines, fields, control)
    })
}

fn step_controlled<C: NativeSchemaControl>(control: &mut C) -> Result<RecordSpec, semio_framework_value::ValueError> {
    scalar_spec_controlled(Some("move"), RecordLayout::Inline, [(0, "to", Shape::Coord(3))], control)
}

fn wait_controlled<C: NativeSchemaControl>(control: &mut C) -> Result<RecordSpec, semio_framework_value::ValueError> {
    scalar_spec_controlled(Some("wait"), RecordLayout::Inline, [(0, "ms", Shape::UInt)], control)
}

fn row_controlled<C: NativeSchemaControl>(control: &mut C) -> Result<RecordSpec, semio_framework_value::ValueError> {
    scalar_spec_controlled(None, RecordLayout::Inline, [(0, "x", Shape::Float), (1, "y", Shape::Float)], control)
}

fn inner_producer() -> RecordSpecProducer { RecordSpecProducer { ordinary: inner_spec, decoding: |control| inner_controlled(control), encoding: |control| inner_controlled(control) } }
fn inner_changed_producer() -> RecordSpecProducer { RecordSpecProducer { ordinary: inner_changed_spec, decoding: |control| inner_changed_controlled(control), encoding: |control| inner_changed_controlled(control) } }
fn other_producer() -> RecordSpecProducer { RecordSpecProducer { ordinary: other_spec, decoding: |control| other_controlled(control), encoding: |control| other_controlled(control) } }
fn node_producer() -> RecordSpecProducer { RecordSpecProducer { ordinary: node_spec, decoding: |control| node_controlled(control), encoding: |control| node_controlled(control) } }
fn node_twin_producer() -> RecordSpecProducer { RecordSpecProducer { ordinary: node_twin_spec, decoding: |control| node_twin_controlled(control), encoding: |control| node_twin_controlled(control) } }
fn step_producer() -> RecordSpecProducer { RecordSpecProducer { ordinary: step_spec, decoding: |control| step_controlled(control), encoding: |control| step_controlled(control) } }
fn wait_producer() -> RecordSpecProducer { RecordSpecProducer { ordinary: wait_spec, decoding: |control| wait_controlled(control), encoding: |control| wait_controlled(control) } }
fn row_producer() -> RecordSpecProducer { RecordSpecProducer { ordinary: row_spec, decoding: |control| row_controlled(control), encoding: |control| row_controlled(control) } }

