    fn allocated(length:usize,control:&mut NativeEncodeControl<'_>)->Result<Self,OutputError>{Ok(Self{bytes:Some(control.allocate_vec(length)?),length:0})}
    fn bytes(&mut self,bytes:&[u8],control:&mut NativeEncodeControl<'_>)->Result<(),OutputError>{self.length=self.length.checked_add(bytes.len()).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"Pack output length overflow"))?;if let Some(output)=&mut self.bytes{if bytes.len()>output.capacity()-output.len(){return Err(ValueError::new(ValueRefusalKind::InvariantViolated,"Pack output exceeded admitted length").into())}control.scoped_stage(|control| -> ::core::result::Result<(),OutputError> {control.begin_stage(bytes.len())?;for fragment in bytes.chunks(65536){output.extend_from_slice(fragment);control.advance(fragment.len())?;}Ok::<_,OutputError>(())})?;}Ok(())}
